#include "sys_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void sys_wake (Wake_Status wake_status)
{
	if (wake_status == s_SLEEP)
	{
      #ifdef DEV_LPC_236x
		VICIntEnClr |= (1u << 4) ;
      #endif
	  
      PCONP &= ~(1u << 1) ;	// Turn off Timer 0 clock
	}	
	else		// wake
	{
	  PCONP |= (1u << 1) ;	// Turn on Timer 0 clock
      
      #ifdef DEV_LPC_236x
		VICIntEnable |= (1u << 4) ;
      #endif
	}
}
